DELETE FROM jobs WHERE industry ILIKE '%charity%' AND NOT (
  lower(title) LIKE '%charit%' OR lower(title) LIKE '%fundrais%' OR lower(title) LIKE '%nonprofit%' OR lower(title) LIKE '%non-profit%' OR lower(title) LIKE '%volunte%' OR lower(title) LIKE '%philanthrop%' OR lower(title) LIKE '%donor%' OR lower(title) LIKE '%grant%' OR lower(title) LIKE '%ngo%' OR lower(title) LIKE '%aid %' OR lower(title) LIKE '%humanitarian%' OR lower(title) LIKE '%community%' OR lower(title) LIKE '%social impact%' OR lower(title) LIKE '%giving%'
) AND NOT (
  lower(company) LIKE '%charit%' OR lower(company) LIKE '%foundation%' OR lower(company) LIKE '%trust%' OR lower(company) LIKE '%oxfam%' OR lower(company) LIKE '%red cross%' OR lower(company) LIKE '%unicef%' OR lower(company) LIKE '%save the children%' OR lower(company) LIKE '%nspcc%' OR lower(company) LIKE '%rspca%' OR lower(company) LIKE '%macmillan%' OR lower(company) LIKE '%cancer research%' OR lower(company) LIKE '%british heart%' OR lower(company) LIKE '%quilombo%' OR lower(company) LIKE '%fundrais%' OR lower(company) LIKE '%volunteer%' OR lower(company) LIKE '%nonprofit%' OR lower(company) LIKE '%non-profit%' OR lower(company) LIKE '%goodstack%' OR lower(company) LIKE '%blue state%'
);